select count(1) from meeting_room_apply
where room_id = #{roomId}
  and meeting_date = #{meetingDate}
  and status not in ('5', '6') -- 排除已拒绝和已取消的申请
  and (
      (start_time < #{endTime} and end_time > #{startTime})
  )
   and apply_id != #{applyId}
